import csv,sys,math
def rd(p): return list(csv.DictReader(open(p,newline='',encoding='utf-8')))
def fl(x):
    try:return float(x)
    except:return float('nan')
o={(r['hyp'],r['pop'],r['src'],r['month']):r for r in rd(sys.argv[1])}
n=rd(sys.argv[2])
diff={};cells=set()
for r in n:
    k=(r['hyp'],r['pop'],r['src'],r['month'])
    q=o.get(k)
    if not q: continue
    for c in q:
        if c not in r: continue
        x,y=fl(q[c]),fl(r[c])
        if q[c]!=r[c] and not (math.isnan(x) and math.isnan(y)) and not (x==y) and abs(x-y)>1e-9:
            diff[c]=diff.get(c,0)+1; cells.add(k)
print(len(cells),'cells differ'); print({c:v for c,v in diff.items()})
EOF
